/** Versioned little-endian codebooks. Generated bytes are never shipped. */
import { CODEBOOK_CHANNELS } from './codebook-features.js';
import { attachQuery } from './codebook-search.js';

export const CODEBOOK_VERSION = 1;
export const ROW_KINDS = Object.freeze([
  'neutral',
  'vowel',
  'nasalVowel',
  'consonant',
  'mixture',
  'perturbed',
  'randomVowel',
]);
const HEADER = 80;
const FIELDS = [
  ['articulation', Uint8Array, 12],
  ['formants', Int16Array, 8],
  ['envelope', Uint8Array, 24],
  ['key', Float32Array, 6],
  ['phone', Uint16Array, 1],
  ['tree', Int32Array, 4],
];
const ROW_BYTES = 94;

export function serializeCodebook(book) {
  const bytes = new Uint8Array(HEADER + ROW_BYTES * book.size);
  const view = new DataView(bytes.buffer);
  view.setUint32(0, 0x31424356, true);
  view.setUint32(4, CODEBOOK_VERSION, true);
  view.setUint32(8, book.id, true);
  view.setUint32(12, book.size, true);
  view.setFloat64(16, book.lengthScale, true);
  view.setFloat64(64, book.referenceLength, true);
  ROW_KINDS.forEach((kind, i) =>
    view.setUint32(24 + 4 * i, book.stats.rows[kind] ?? 0, true)
  );
  view.setUint32(52, book.stats.nasalRows, true);
  view.setFloat64(56, book.stats.nonUniqueShare, true);
  let offset = HEADER;
  for (const [name, Type, width] of FIELDS) {
    const values = book[name];
    if (!(values instanceof Type) || values.length !== book.size * width) {
      throw new RangeError(`Invalid codebook ${name}`);
    }
    for (const value of values) {
      if (Type === Uint8Array) {
        view.setUint8(offset, value);
      } else if (Type === Int16Array) {
        view.setInt16(offset, value, true);
      } else if (Type === Uint16Array) {
        view.setUint16(offset, value, true);
      } else if (Type === Float32Array) {
        view.setFloat32(offset, value, true);
      } else {
        view.setInt32(offset, value, true);
      }
      offset += Type.BYTES_PER_ELEMENT;
    }
  }
  return bytes;
}

// Validate every serialized dimension and tree edge before lookup.
// eslint-disable-next-line complexity
export function parseCodebook(bytes) {
  if (!(bytes instanceof Uint8Array) || bytes.byteLength < HEADER) {
    throw new RangeError('Truncated codebook');
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const size = view.getUint32(12, true),
    scale = view.getFloat64(16, true),
    referenceLength = view.getFloat64(64, true);
  if (
    view.getUint32(0, true) !== 0x31424356 ||
    view.getUint32(4, true) !== CODEBOOK_VERSION ||
    size < 1 ||
    size > 100000 ||
    bytes.length !== HEADER + ROW_BYTES * size ||
    !Number.isFinite(scale) ||
    scale <= 0 ||
    !Number.isFinite(referenceLength) ||
    referenceLength < 11 ||
    referenceLength > 20
  ) {
    throw new RangeError('Invalid codebook header or size');
  }
  const rows = {};
  ROW_KINDS.forEach(
    (kind, i) => (rows[kind] = view.getUint32(24 + 4 * i, true))
  );
  const nasalRows = view.getUint32(52, true),
    nonUniqueShare = view.getFloat64(56, true);
  if (
    Object.values(rows).reduce((a, b) => a + b, 0) !== size ||
    nasalRows > Math.floor(size / 10) ||
    !Number.isFinite(nonUniqueShare) ||
    nonUniqueShare < 0 ||
    nonUniqueShare > 1
  ) {
    throw new RangeError('Invalid codebook statistics');
  }
  const book = {
    version: CODEBOOK_VERSION,
    id: view.getUint32(8, true),
    size,
    lengthScale: scale,
    referenceLength,
    channels: CODEBOOK_CHANNELS,
    stats: { rows, nasalRows, nonUniqueShare, buildMilliseconds: 0 },
  };
  let offset = HEADER;
  for (const [name, Type, width] of FIELDS) {
    const values = new Type(size * width);
    for (let i = 0; i < values.length; i++) {
      if (Type === Uint8Array) {
        values[i] = view.getUint8(offset);
      } else if (Type === Int16Array) {
        values[i] = view.getInt16(offset, true);
      } else if (Type === Uint16Array) {
        values[i] = view.getUint16(offset, true);
      } else if (Type === Float32Array) {
        values[i] = view.getFloat32(offset, true);
      } else {
        values[i] = view.getInt32(offset, true);
      }
      offset += Type.BYTES_PER_ELEMENT;
    }
    book[name] = values;
  }
  const seen = new Uint8Array(size),
    parents = new Uint8Array(size),
    depth = new Uint8Array(size);
  parents[0] = 1;
  for (let node = 0; node < size; node++) {
    const row = book.tree[node * 4],
      dimension = book.tree[node * 4 + 1];
    if (
      row < 0 ||
      row >= size ||
      seen[row] ||
      dimension < 0 ||
      dimension >= 6
    ) {
      throw new RangeError('Invalid codebook tree');
    }
    seen[row] = 1;
    for (let d = 0; d < 6; d++) {
      if (!Number.isFinite(book.key[row * 6 + d])) {
        throw new RangeError('Invalid codebook key');
      }
    }
    for (let side = 2; side < 4; side++) {
      const child = book.tree[node * 4 + side];
      if (
        child !== -1 &&
        (child <= node || child >= size || ++parents[child] !== 1)
      ) {
        throw new RangeError('Invalid codebook child');
      }
      if (child >= 0) {
        depth[child] = depth[node] + 1;
        if (depth[child] > 62) {
          throw new RangeError('Codebook tree exceeds query stack');
        }
      }
    }
  }
  if (parents.some((n) => n !== 1)) {
    throw new RangeError('Disconnected codebook tree');
  }
  return attachQuery(book);
}
